{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Los Angeles RSO allowable rent increase","requirement":"A landlord may raise rent on an RSO unit once every 12 months by the allowable rent increase percentage. Since February 2, 2026, no additional utility percentage increase or extra 10% for a dependent is allowed; a 10% increase for an additional tenant remains allowed.","key_value":"once every 12 months; annual allowable increase set by LAHD","coverage_conditions":"Rental properties first built on or before October 1, 1978, plus replacement units under LAMC Section 151.28, including apartments, condominiums, townhomes, duplexes, two or more single-family homes on one parcel, ADUs, JADUs and mobile homes.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","text":"Landlord may apply for an exemption where the monthly rent charged on or before May 31, 1978 met the luxury threshold."}],"per_tenancy":"Rent amount is not regulated for condominium and townhome tenancies that commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:"]},"exemptions":"Condominium and townhome rent amounts are not regulated for tenancies commenced after December 31, 1995; luxury exemption on application; temporary exemptions.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles RSO legal reasons for eviction and no-fault relocation","requirement":"A landlord may end an RSO tenancy only for the listed at-fault or no-fault causes. No-fault evictions require a filed landlord declaration, 30- or 60-day notice and relocation assistance; termination notices must be filed with LAHD within three business days of service.","key_value":"30-day and 60-day notice (120 days for some); file with LAHD within 3 business days","coverage_conditions":"All rental units subject to the City's Rent Stabilization Ordinance: properties first built on or before October 1, 1978, plus replacement units, including apartments, duplexes, condominiums and ADUs.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"},{"type":"other","text":"Landlord may apply for an exemption where the monthly rent charged on or before May 31, 1978 met the luxury threshold."}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:","All notices to terminate a tenancy for all rental units subject to City's Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant per Los Angeles Municipal Code 151.09.C.9 & 165.05.B.5."]},"exemptions":"Units exempt from the RSO, such as condominium and townhome tenancies whose rent amount is not regulated.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"No-fault evictions require the payment of relocation assistance.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
